import os
import shutil
import stat

PRE_COMMIT_HOOK_CONTENT = """#!/bin/sh
# Auto-generated by stampver
# Universal pre-commit version stamper

if command -v stampver >/dev/null 2>&1; then
    stampver stamp --stage
elif command -v uv >/dev/null 2>&1; then
    uv run stampver stamp --stage
elif command -v python >/dev/null 2>&1; then
    python -m stampver.cli stamp --stage
else
    echo "[stampver] ERROR: stampver executable not found in PATH." >&2
    exit 1
fi
"""


def install_pre_commit_hook(target_dir: str = ".") -> tuple[bool, str]:
    git_dir = os.path.join(target_dir, ".git")
    if not os.path.isdir(git_dir):
        return False, f"Not a git repository: {os.path.abspath(target_dir)}"

    hooks_dir = os.path.join(git_dir, "hooks")
    os.makedirs(hooks_dir, exist_ok=True)
    hook_path = os.path.join(hooks_dir, "pre-commit")

    backup_msg = ""
    if os.path.exists(hook_path) and os.path.getsize(hook_path) > 0:
        try:
            with open(hook_path, encoding="utf-8") as f:
                existing_content = f.read()
            if "# Auto-generated by stampver" not in existing_content:
                backup_path = os.path.join(hooks_dir, "pre-commit.bak")
                shutil.copyfile(hook_path, backup_path)
                backup_msg = f" (backed up existing hook to {os.path.relpath(backup_path, target_dir)})"
        except Exception:
            pass

    with open(hook_path, "w", encoding="utf-8") as f:
        f.write(PRE_COMMIT_HOOK_CONTENT)

    # Make executable on Unix/Linux/macOS
    try:
        st = os.stat(hook_path)
        os.chmod(hook_path, st.st_mode | stat.S_IEXEC)
    except Exception:
        pass

    return (
        True,
        f"Successfully installed pre-commit hook at {os.path.relpath(hook_path, target_dir)}{backup_msg}",
    )

